return ['domain'=>'octopus-image-optimizer','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'OIO – Octopus Image Optimizer 0.1.4','pot-creation-date'=>'2026-10-26T21:14:55+00:00','po-revision-date'=>'2026-10-26 08:00+0100','messages'=>['OIO – Octopus Image Optimizer'=>'OIO – Octopus Image Optimizer','https://github.com/Striffly/octopus-image-optimizer'=>'https://github.com/Striffly/octopus-image-optimizer','Compresses JPG and PNG images and converts them to WebP and AVIF on your own server, with cwebp, avifenc, jpegoptim and optipng. Free, unlimited, no API key.'=>'Compresse les images JPG et PNG et les convertit en WebP et AVIF sur votre propre serveur, avec cwebp, avifenc, jpegoptim et optipng. Gratuit, illimité, sans clé d’API.','Clément Gayot'=>'Clément Gayot','https://github.com/Striffly'=>'https://github.com/Striffly','A job is already running, or there is no image to process.'=>'Une tâche est déjà en cours, ou il n’y a aucune image à traiter.','Optimised'=>'Optimisée','To optimise'=>'À optimiser','Older settings'=>'Anciens réglages','Error'=>'Erreur','Optimisation'=>'Optimisation','Original: %s'=>'Original : %s','Compressed: %1$s (%2$s)'=>'Compressée : %1$s (%2$s)','With WebP and AVIF: %1$s (%2$s)'=>'Avec WebP et AVIF : %1$s (%2$s)','WebP and AVIF files: %s'=>'Fichiers WebP et AVIF : %s','The site serves the WebP and AVIF.'=>'Le site sert les WebP et AVIF.','The site serves the JPG or PNG.'=>'Le site sert le JPG ou le PNG.','Optimise again'=>'Optimiser à nouveau','Optimise'=>'Optimiser','Restore original'=>'Restaurer l’original','You cannot optimise this image.'=>'Vous ne pouvez pas optimiser cette image.','You cannot restore this image.'=>'Vous ne pouvez pas restaurer cette image.','Octopus Image Optimizer is already processing %s, try again in a moment.'=>'Octopus Image Optimizer traite déjà %s, réessayez dans un instant.','Octopus Image Optimizer restored the original of %s.'=>'Octopus Image Optimizer a restauré l’original de %s.','Octopus Image Optimizer removed its files of %s, but its original is missing: it stays compressed.'=>'Octopus Image Optimizer a supprimé ses fichiers de %s, mais son original est introuvable : l’image reste compressée.','Octopus Image Optimizer optimised %s.'=>'Octopus Image Optimizer a optimisé %s.','the image uses CMYK colours (a print format) that the library cannot read.'=>'l’image utilise des couleurs CMJN (un format d’impression) que la bibliothèque ne sait pas lire.','the server disk is full.'=>'le disque du serveur est plein.','the image is too big for the PHP memory: install the library, or lower the maximum image size.'=>'l’image est trop grande pour la mémoire de PHP : installez la bibliothèque, ou réduisez la taille maximale des images.','the file could not be written, check the permissions of the uploads folder.'=>'le fichier n’a pas pu être écrit, vérifiez les droits du dossier uploads.','the image file is damaged or incomplete, WordPress cannot read it.'=>'le fichier de l’image est endommagé ou incomplet, WordPress ne peut pas le lire.','the image file seems damaged or incomplete.'=>'le fichier de l’image semble endommagé ou incomplet.','the library does not work on the server, check its installation.'=>'la bibliothèque ne fonctionne pas sur le serveur, vérifiez son installation.','Octopus Image Optimizer could not fully optimise some images:'=>'Octopus Image Optimizer n’a pas pu optimiser entièrement certaines images :','%1$s failed: %2$s'=>'%1$s en échec : %2$s','Technical details'=>'Détails techniques','an unexpected error occurred, see the technical details.'=>'une erreur inattendue s’est produite, voir les détails techniques.','Settings'=>'Réglages','Buy me a coffee'=>'Offrez-moi un café','Restore original images'=>'Restaurer les images originales','Before deactivating OIO'=>'Avant de désactiver OIO','Your theme calls %s'=>'Votre thème appelle %s','%s: the pages using it will break while OIO is deactivated.'=>'%s : les pages qui l’utilisent casseront tant qu’OIO sera désactivé.','OIO has optimised %1$s. Deactivating or deleting OIO keeps them as they are: compressed, with their WebP and AVIF versions, and their originals in %2$s.'=>'OIO a optimisé %1$s. Désactiver ou supprimer OIO les laisse telles quelles : compressées, avec leurs versions WebP et AVIF, et leurs originaux dans %2$s.','If you are going to delete OIO, run %s first to get your original images back and remove every OIO file.'=>'Si vous comptez supprimer OIO, lancez d’abord %s pour récupérer vos images originales et retirer tous les fichiers d’OIO.','Deactivate anyway'=>'Désactiver quand même','Cancel'=>'Annuler','Overview'=>'Vue d’ensemble','Delivery'=>'Diffusion','Maintenance'=>'Maintenance','A format has no library'=>'Un format n’a pas de bibliothèque','QR code of the Bitcoin address'=>'QR code de l’adresse Bitcoin','PHP cannot run programs on this server.'=>'PHP ne peut pas lancer de programmes sur ce serveur.','%1$s and %2$s are disabled (%3$s): the libraries cannot run, even installed, so the JPG and PNG images are not compressed. Ask your host to enable %1$s. Meanwhile, GD or Imagick make the WebP and AVIF when they can.'=>'%1$s et %2$s sont désactivées (%3$s) : les bibliothèques ne peuvent pas tourner, même installées, et les images JPG et PNG ne sont donc pas compressées. Demandez à votre hébergeur d’activer %1$s. En attendant, GD ou Imagick créent les WebP et AVIF quand ils le peuvent.','%s saved'=>'%s économisés','%s on what the site serves'=>'%s sur ce que sert le site','%s with WebP and AVIF served'=>'%s en servant les WebP et AVIF','On the disk'=>'Sur le disque','%s of originals kept'=>'%s d’originaux conservés','%s of WebP and AVIF'=>'%s de WebP et AVIF','Ready to squeeze'=>'Prêt à presser','OIO optimises your images on your own server: free, unlimited, and they never leave it.'=>'OIO optimise vos images sur votre propre serveur : gratuit, illimité, et elles n’en sortent jamais.','Optimise the media library'=>'Optimiser la médiathèque','Formats'=>'Formats','installed'=>'installé','%s not installed'=>'%s non installé','%s cannot run'=>'%s ne peut pas tourner','not installed'=>'non installé','cannot run'=>'ne peut pas tourner','These jobs run in the background, page closed or not, with the lowest priority on the server.'=>'Ces tâches tournent en arrière-plan, page fermée ou non, avec la priorité la plus basse sur le serveur.','All your images are optimised.'=>'Toutes vos images sont optimisées.','Nothing left to do: the new ones are optimised on upload.'=>'Plus rien à faire : les nouvelles sont optimisées dès leur téléversement.','New images'=>'Nouvelles images','Not optimised yet, or their optimisation failed.'=>'Pas encore optimisées, ou leur optimisation a échoué.','Optimise new images'=>'Optimiser les nouvelles images','Outdated images'=>'Images obsolètes','Optimised before a quality, a format, the maximum size or the thumbnail sizes changed. Optimised again from their originals.'=>'Optimisées avant le changement d’une qualité, d’un format, de la taille maximale ou des tailles de miniatures. Optimisées à nouveau depuis leurs originaux.','Re-optimise outdated images'=>'Réoptimiser les images obsolètes','All images'=>'Toutes les images','Every image optimised again from its original, with its thumbnails made again.'=>'Chaque image optimisée à nouveau depuis son original, avec ses miniatures refaites.','Re-optimise all images from their originals, with their thumbnails? This can take a while.'=>'Réoptimiser toutes les images depuis leurs originaux, avec leurs miniatures ? Cela peut prendre du temps.','Re-optimise all images'=>'Réoptimiser toutes les images','New uploads are optimised right away.'=>'Les nouveaux téléversements sont optimisés aussitôt.','See each image in the Media library'=>'Voir chaque image dans la médiathèque','Your server'=>'Votre serveur','Apache: ticking it writes the rules below in %s, unticking it removes them.'=>'Apache : en cochant, OIO écrit les règles ci-dessous dans %s, et les retire en décochant.','%s: add the rules below to its configuration, then tick this box.'=>'%s : ajoutez les règles ci-dessous à sa configuration, puis cochez cette case.','%1$s does not read %2$s files: add the rules below to its configuration, then tick this box so that OIO counts the bytes saved. The HTML does not change, and every image is served, CSS backgrounds and custom themes included.'=>'%1$s ne lit pas les fichiers %2$s : ajoutez les règles ci-dessous à sa configuration, puis cochez cette case pour qu’OIO compte les octets économisés. Le HTML ne change pas, et toutes les images sont servies, arrière-plans CSS et thèmes sur mesure compris.','Generate'=>'Générer','The WebP and AVIF versions are made while the images are optimised.'=>'Les versions WebP et AVIF sont créées pendant l’optimisation des images.','of %s image has its WebP or AVIF version'=>'sur %s image a sa version WebP ou AVIF' . "\0" . 'sur %s images ont leur version WebP ou AVIF','Save changes'=>'Enregistrer les modifications','Test'=>'Tester','Are the WebP and AVIF files served with their type?'=>'Les fichiers WebP et AVIF sont-ils servis avec leur type ?','Does the server answer the image with them?'=>'Le serveur les renvoie-t-il à la place de l’image ?','Are the originals kept private?'=>'Les originaux restent-ils privés ?','Run the test'=>'Lancer le test','Test results'=>'Résultats du test','Rules and code'=>'Règles et code','Rewrite rules for Apache and LiteSpeed'=>'Règles de réécriture pour Apache et LiteSpeed','Written in uploads/.htaccess'=>'Écrites dans uploads/.htaccess','Not written'=>'Non écrites','OIO writes them in %s when the server option is on, and removes them when it is off.'=>'OIO les écrit dans %s quand l’option serveur est activée, et les retire quand elle est désactivée.','In %s, written by OIO when the server option is on.'=>'Dans %s, écrites par OIO quand l’option serveur est activée.','Rewrite rules for nginx'=>'Règles de réécriture pour nginx','Add them to the configuration of the site, reload nginx, then tick the server option.'=>'Ajoutez-les à la configuration du site, rechargez nginx, puis cochez l’option serveur.','Recommended: install %s'=>'Recommandé : installer %s','How to install %s'=>'Comment installer %s','How to install %1$s, for the %2$s'=>'Comment installer %1$s, pour la %2$s','Remove WebP and AVIF'=>'Supprimer les WebP et AVIF','Deletes the WebP and AVIF files of the %s images processed. The JPG and PNG files stay compressed, and the originals kept.'=>'Supprime les fichiers WebP et AVIF des %s images traitées. Les fichiers JPG et PNG restent compressés, et les originaux conservés.','I understand the WebP and AVIF files will be deleted, until the images are optimised again.'=>'Je comprends que les fichiers WebP et AVIF seront supprimés, jusqu’à ce que les images soient à nouveau optimisées.','Puts the original images back and deletes every file made by OIO (WebP, AVIF, backups). Do it before deleting OIO: deleting it keeps the files as they are.'=>'Remet les images originales en place et supprime tous les fichiers créés par OIO (WebP, AVIF, sauvegardes). À faire avant de supprimer OIO : le supprimer laisse les fichiers tels quels.','I understand the images will no longer be optimised, and their WebP and AVIF files will be deleted.'=>'Je comprends que les images ne seront plus optimisées, et que leurs fichiers WebP et AVIF seront supprimés.','The background jobs need the dependencies of OIO: run %1$s in its folder. WP-CLI (%2$s) works without them.'=>'Les tâches en arrière-plan ont besoin des dépendances d’OIO : lancez %1$s dans son dossier. WP-CLI (%2$s) fonctionne sans elles.','Pause'=>'Pause','Resume'=>'Reprendre','see the errors in the Media library'=>'voir les erreurs dans la médiathèque','Dismiss'=>'Ignorer','Custom themes: the %s helper'=>'Thèmes sur mesure : la fonction %s','Images output with your own markup (e.g. from an ACF field) are not wrapped in a %1$s by the HTML option: serve them from the server, or use the %2$s helper, which returns their %1$s whatever the options.'=>'Les images affichées avec votre propre balisage (par exemple depuis un champ ACF) ne sont pas enveloppées dans un %1$s par l’option HTML : servez-les depuis le serveur, ou utilisez la fonction %2$s, qui renvoie leur %1$s quelles que soient les options.','The second argument is the class of the %1$s element. Pass %2$s as third argument to output %3$s and %4$s for a JavaScript lazy loader. Keep the %5$s check: without it, the pages break while OIO is deactivated.'=>'Le deuxième argument est la classe de l’élément %1$s. Passez %2$s en troisième argument pour produire %3$s et %4$s, pour un chargement différé en JavaScript. Gardez la vérification %5$s : sans elle, les pages cassent tant qu’OIO est désactivé.','imagesOptimised'=>'Optimisées','imagesTo optimise'=>'À optimiser','imagesOlder settings'=>'Anciens réglages','imagesError'=>'En erreur','Active'=>'Actif','Library unavailable'=>'Bibliothèque indisponible','Disabled'=>'Désactivé','Copy'=>'Copier','More about: %s'=>'En savoir plus : %s','Compress JPG images'=>'Compresser les images JPG','Compresses the JPG images in place with jpegoptim, and makes them progressive. Their originals are kept.'=>'Compresse les images JPG sur place avec jpegoptim, et les rend progressives. Leurs originaux sont conservés.','Quality'=>'Qualité','lossy compression'=>'compression avec perte','Compress PNG images'=>'Compresser les images PNG','Compresses the PNG images in place with oxipng or optipng, after pngquant when lossy. Their originals are kept.'=>'Compresse les images PNG sur place avec oxipng ou optipng, après pngquant avec perte. Leurs originaux sont conservés.','Compression'=>'Compression','Lossless'=>'Sans perte','Lossy (pngquant)'=>'Avec perte (pngquant)','Lossy: often 60 to 80 % lighter, for graphics and screenshots. Needs pngquant.'=>'Avec perte : souvent 60 à 80 % plus léger, pour les graphiques et les captures d’écran. Nécessite pngquant.','Optimisation level'=>'Niveau d’optimisation','Lossy quality'=>'Qualité avec perte','%s makes the WebP files for now, in the PHP process. cwebp runs apart from PHP, and makes the PNG graphics and screenshots much lighter.'=>'%s crée les fichiers WebP pour l’instant, dans le processus de PHP. cwebp tourne à part, et rend les graphiques et captures d’écran PNG bien plus légers.','Make WebP versions'=>'Créer les versions WebP','Makes a WebP version of each image and thumbnail (<code>photo.jpg.webp</code>), lighter than the JPG or PNG.'=>'Crée une version WebP de chaque image et miniature (<code>photo.jpg.webp</code>), plus légère que le JPG ou le PNG.','%s makes the AVIF files for now, in the PHP process. avifenc runs apart from PHP, on several threads, and keeps the colours of the PNG images sharper.'=>'%s crée les fichiers AVIF pour l’instant, dans le processus de PHP. avifenc tourne à part, sur plusieurs threads, et garde les couleurs des images PNG plus nettes.','Make AVIF versions'=>'Créer les versions AVIF','Makes an AVIF version of each image and thumbnail (<code>photo.jpg.avif</code>), often the lightest. Kept only when lighter than the WebP and the JPG or PNG.'=>'Crée une version AVIF de chaque image et miniature (<code>photo.jpg.avif</code>), souvent la plus légère. Conservée seulement si elle est plus légère que le WebP et que le JPG ou le PNG.','Maximum image size'=>'Taille maximale des images','Serve'=>'Servir','Each browser gets the lightest version it reads: AVIF, then WebP, or the JPG or PNG for older ones. Choose one way, or both.'=>'Chaque navigateur reçoit la version la plus légère qu’il sait lire : AVIF, puis WebP, ou le JPG ou PNG pour les plus anciens. Choisissez une méthode, ou les deux.','In the HTML, with <picture>'=>'Dans le HTML, avec <picture>','Wraps the images of the content in a <code>&lt;picture&gt;</code>. Untick it if the layout breaks.'=>'Enveloppe les images du contenu dans un <code>&lt;picture&gt;</code>. Décochez si la mise en page casse.','Images of the post content, featured images and galleries are wrapped in a <code>&lt;picture&gt;</code> tag offering the AVIF and WebP versions. Works on every server. <strong>Untick this if your theme layout breaks around images.</strong>'=>'Les images du contenu, les images mises en avant et les galeries sont enveloppées dans une balise <code>&lt;picture&gt;</code> qui propose les versions AVIF et WebP. Fonctionne sur tous les serveurs. <strong>Décochez cette option si la mise en page de votre thème casse autour des images.</strong>','From the server, with rewrite rules'=>'Depuis le serveur, avec des règles de réécriture','Every image, CSS backgrounds included, the HTML unchanged.'=>'Toutes les images, arrière-plans CSS compris, sans toucher au HTML.','The server answers <code>photo.jpg</code> with <code>photo.jpg.avif</code> or <code>.webp</code> when the browser reads them. The HTML does not change, and every image is served, CSS backgrounds and custom themes included. A CDN must vary its cache on the <code>Accept</code> header.'=>'Le serveur répond à <code>photo.jpg</code> avec <code>photo.jpg.avif</code> ou <code>.webp</code> quand le navigateur sait les lire. Le HTML ne change pas, et toutes les images sont servies, arrière-plans CSS et thèmes sur mesure compris. Un CDN doit faire varier son cache selon l’en-tête <code>Accept</code>.','PHP cannot run programs: proc_open() and exec() are disabled, the libraries cannot run.'=>'PHP ne peut pas lancer de programmes : proc_open() et exec() sont désactivées, les bibliothèques ne peuvent pas tourner.','%s (optional)'=>'%s (facultatif)','--%1$s is on or off: use --%1$s or --no-%1$s.'=>'--%1$s s’active ou se désactive : utilisez --%1$s ou --no-%1$s.','Formats: %s'=>'Formats : %s','none'=>'aucun','Processing image:'=>'Traitement de l’image :','%s: skipped, another request is processing it.'=>'%s : ignorée, une autre requête la traite.','Processed %1$d image, %2$d with errors: see them in the Media library.'=>'%1$d image traitée, %2$d en erreur : voyez-les dans la médiathèque.' . "\0" . '%1$d images traitées, %2$d en erreur : voyez-les dans la médiathèque.','Successfully processed %d image.'=>'%d image traitée avec succès.' . "\0" . '%d images traitées avec succès.','Removed the WebP and AVIF files of %d image.'=>'Fichiers WebP et AVIF supprimés pour %d image.' . "\0" . 'Fichiers WebP et AVIF supprimés pour %d images.','%s: no original to restore, it stays compressed.'=>'%s : pas d’original à restaurer, elle reste compressée.','Restored %d image.'=>'%d image restaurée.' . "\0" . '%d images restaurées.','%d had no original.'=>'%d n’avait pas d’original.' . "\0" . '%d n’avaient pas d’original.','%d skipped.'=>'%d ignorée.' . "\0" . '%d ignorées.','Measured %d image.'=>'%d image mesurée.' . "\0" . '%d images mesurées.','Originals'=>'Originaux','Compressed JPG and PNG'=>'JPG et PNG compressés','With WebP and AVIF served'=>'En servant les WebP et AVIF','WebP and AVIF files'=>'Fichiers WebP et AVIF','%1$s saved on %2$d image, %3$s: the site serves the WebP and AVIF.'=>'%1$s économisés sur %2$d image, %3$s : le site sert les WebP et AVIF.' . "\0" . '%1$s économisés sur %2$d images, %3$s : le site sert les WebP et AVIF.','%1$s saved on %2$d image, %3$s: the site serves the JPG and PNG, not the WebP and AVIF.'=>'%1$s économisés sur %2$d image, %3$s : le site sert les JPG et PNG, pas les WebP et AVIF.' . "\0" . '%1$s économisés sur %2$d images, %3$s : le site sert les JPG et PNG, pas les WebP et AVIF.','Welcome to the OIO CLI...'=>'Bienvenue dans le CLI d’OIO...','%s active.'=>'%s actif.','Error:'=>'Erreur :','%s not installed, see the settings page of OIO.'=>'%s non installé, voir la page de réglages d’OIO.','%1$s active for %2$s: %3$s not installed, recommended.'=>'%1$s actif pour %2$s : %3$s non installé, recommandé.','OIO could not write the rules in uploads/.htaccess: copy them by hand from the Delivery tab.'=>'OIO n’a pas pu écrire les règles dans uploads/.htaccess : copiez-les à la main depuis l’onglet Diffusion.','Optimise at least one image with its WebP or AVIF version first.'=>'Optimisez d’abord au moins une image avec sa version WebP ou AVIF.','The %1$s files are served as %2$s'=>'Les fichiers %1$s sont servis en %2$s','The browsers ignore a file sent with another type. Apache: %1$s. nginx: add %2$s to mime.types.'=>'Les navigateurs ignorent un fichier envoyé avec un autre type. Apache : %1$s. nginx : ajoutez %2$s à mime.types.','The server answers the image with its %s version'=>'Le serveur répond à l’image avec sa version %s','The server answers the image with the JPG or PNG'=>'Le serveur répond à l’image avec le JPG ou le PNG','The rewrite rules are not applied: check that they are in the configuration of the server, and that mod_rewrite is on (Apache).'=>'Les règles de réécriture ne sont pas appliquées : vérifiez qu’elles sont dans la configuration du serveur, et que mod_rewrite est activé (Apache).','Expected while the server rewrite is off.'=>'Normal tant que la réécriture par le serveur est désactivée.','Caches know the image depends on the browser (Vary: Accept)'=>'Les caches savent que l’image dépend du navigateur (Vary: Accept)','No Vary: Accept header.'=>'Pas d’en-tête Vary: Accept.','Without it, a cache or a CDN can serve an AVIF to a browser that cannot read it. Apache: enable mod_headers (%s).'=>'Sans lui, un cache ou un CDN peut servir un AVIF à un navigateur qui ne sait pas le lire. Apache : activez mod_headers (%s).','The original images are not public'=>'Les images originales ne sont pas publiques','The sample image has no original kept.'=>'L’image testée n’a pas d’original conservé.','They are kept out of the uploads folder.'=>'Elles sont conservées hors du dossier uploads.','Anyone can download them, with their metadata (GPS position of the photos). nginx: add %1$s to the server block, or move them with the %2$s filter.'=>'N’importe qui peut les télécharger, avec leurs métadonnées (position GPS des photos). nginx : ajoutez %1$s au bloc server, ou déplacez-les avec le filtre %2$s.','The site could not be reached: %s'=>'Le site n’a pas pu être joint : %s','its dependencies are missing, run %s in the plugin folder.'=>'ses dépendances manquent, lancez %s dans le dossier de l’extension.','More information'=>'Plus d’informations','Download for Windows'=>'Télécharger pour Windows','Faster'=>'Plus rapide','replaces optipng, on recent systems, or from its <a href="%s" target="_blank" rel="noopener">releases</a>'=>'remplace optipng, sur les systèmes récents, ou depuis ses <a href="%s" target="_blank" rel="noopener">versions publiées</a>','Copied'=>'Copié','Press Ctrl+C'=>'Appuyez sur Ctrl+C','Copied to the clipboard.'=>'Copié dans le presse-papiers.','The code is selected: press Ctrl+C to copy it.'=>'Le code est sélectionné : appuyez sur Ctrl+C pour le copier.','%s image'=>'%s image' . "\0" . '%s images','Testing…'=>'Test en cours…','The test failed.'=>'Le test a échoué.','Run the test again'=>'Relancer le test','%1$s of %2$s check failed: see the results below.'=>'Vérifications en échec : %1$s sur %2$s. Voir les résultats ci-dessous.' . "\0" . 'Vérifications en échec : %1$s sur %2$s. Voir les résultats ci-dessous.','The %s check passed.'=>'%s vérification réussie.' . "\0" . 'Les %s vérifications ont réussi.','Tested on %s.'=>'Testé sur %s.','Optimising'=>'Optimisation','Optimisation complete'=>'Optimisation terminée','Optimisation cancelled'=>'Optimisation annulée','%s image optimised'=>'%s image optimisée' . "\0" . '%s images optimisées','Removing WebP and AVIF'=>'Suppression des WebP et AVIF','WebP and AVIF files removed'=>'Fichiers WebP et AVIF supprimés','Removal cancelled'=>'Suppression annulée','%s image cleaned up'=>'%s image nettoyée' . "\0" . '%s images nettoyées','Restoring the originals'=>'Restauration des originaux','Original images restored'=>'Images originales restaurées','Restore cancelled'=>'Restauration annulée','%s image restored'=>'%s image restaurée' . "\0" . '%s images restaurées','%1$s / %2$s image'=>'%1$s / %2$s image' . "\0" . '%1$s / %2$s images','%1$s, %2$s with errors'=>'%1$s, %2$s en erreur' . "\0" . '%1$s, %2$s en erreur','Paused:'=>'En pause :','Processing'=>'Traitement','%s could not be optimised:'=>'%s n’a pas pu être optimisée :' . "\0" . '%s n’ont pas pu être optimisées :','%s had no original to restore, it stays compressed.'=>'%s n’avait pas d’original à restaurer, elle reste compressée.' . "\0" . '%s n’avaient pas d’original à restaurer, elles restent compressées.','Stopped after %1$s of %2$s image'=>'Arrêtée après %1$s sur %2$s image' . "\0" . 'Arrêtée après %1$s sur %2$s images','The images already processed stay processed.'=>'Les images déjà traitées le restent.','%1$s in %2$s'=>'%1$s en %2$s','%1$d h %2$d min'=>'%1$d h %2$d min','%1$d min %2$d s'=>'%1$d min %2$d s','%d s'=>'%d s','The job could not start.'=>'La tâche n’a pas pu démarrer.','Optimise images'=>'Optimiser les images','OIO is free, and will stay so. If it saves you time or bytes, you can buy me a coffee:'=>'OIO est gratuit, et le restera. S’il vous fait gagner du temps ou des octets, vous pouvez m’offrir un café :','New uploads wait here, as new images.'=>'Les nouveaux téléversements attendent ici, parmi les nouvelles images.','Optimise them on upload'=>'Les optimiser au téléversement','Uploads'=>'Téléversements','What happens to the images added to the media library.'=>'Ce que deviennent les images ajoutées à la médiathèque.','Optimise new uploads'=>'Optimiser les nouveaux téléversements','Each image added to the media library is optimised right away. Unticked, they wait in the Optimise tab, as new images.'=>'Chaque image ajoutée à la médiathèque est optimisée aussitôt. Décoché, les images attendent dans l’onglet Optimiser, parmi les nouvelles images.','Saved'=>'Enregistré','Not saved'=>'Non enregistré','The new uploads will wait here, to optimise when you like.'=>'Les nouveaux téléversements attendront ici, à optimiser quand vous voudrez.','Requests an optimised image as a browser would.'=>'Demande une image optimisée comme le ferait un navigateur.','OIO could not remove its rules from uploads/.htaccess: remove them by hand, between the lines with Octopus Image Optimizer.'=>'OIO n’a pas pu retirer ses règles de uploads/.htaccess : retirez-les à la main, entre les lignes avec Octopus Image Optimizer.','Not applied'=>'Non appliqué','the library took too long on this image and was stopped: optimise it again, or lower the maximum image size.'=>'la bibliothèque a mis trop de temps sur cette image et a été arrêtée : optimisez-la à nouveau, ou baissez la taille maximale des images.','The server refuses the rules of uploads/.htaccess (error 500 on every image): OIO removed them. Ask your host to allow them (AllowOverride FileInfo), or serve the WebP and AVIF files in the HTML.'=>'Le serveur refuse les règles de uploads/.htaccess (erreur 500 sur chaque image) : OIO les a retirées. Demandez à votre hébergeur de les autoriser (AllowOverride FileInfo), ou servez les fichiers WebP et AVIF dans le HTML.','The server answers with an error: it refuses the rules of uploads/.htaccess, and serves no image of the uploads folder. Untick the server option, then ask your host to allow them (AllowOverride FileInfo).'=>'Le serveur répond par une erreur : il refuse les règles de uploads/.htaccess, et ne sert plus aucune image du dossier uploads. Décochez l’option serveur, puis demandez à votre hébergeur de les autoriser (AllowOverride FileInfo).','Optimising…'=>'Optimisation…','Waiting'=>'En attente','Octopus Image Optimizer will optimise %s in a moment.'=>'Octopus Image Optimizer va optimiser %s dans un instant.','Being processed, try again in a moment.'=>'En cours de traitement, réessayez dans un instant.','Original missing: the image stays compressed.'=>'Original manquant : l’image reste compressée.','Optimised!'=>'Optimisée !','Restoring…'=>'Restauration…','Restored!'=>'Restaurée !','optipng compresses the PNG images for now. Once installed, oxipng replaces it on its own: the files are lighter at the same level, and it is a little faster.'=>'optipng compresse les images PNG pour l’instant. Une fois installé, oxipng le remplace de lui-même : les fichiers sont plus légers au même niveau, et il est un peu plus rapide.','Speed'=>'Vitesse','The site did not answer: try again.'=>'Le site n’a pas répondu : réessayez.','%1$s · an image waits for another request, %2$s second at most'=>'%1$s · une image attend une autre requête, %2$s seconde au plus' . "\0" . '%1$s · une image attend une autre requête, %2$s secondes au plus','From %1$d to %2$d, %3$d by default.'=>'De %1$d à %2$d, %3$d par défaut.','From o%1$d (fastest) to o%2$d (smallest files), o%3$d by default.'=>'De o%1$d (le plus rapide) à o%2$d (les fichiers les plus légers), o%3$d par défaut.','The quality pngquant aims at, %3$d by default.'=>'La qualité visée par pngquant, %3$d par défaut.','From %1$d to %2$d (lossless), %3$d by default.'=>'De %1$d à %2$d (sans perte), %3$d par défaut.','From %1$d to %2$d (fastest, heavier files), %3$d by default.'=>'De %1$d à %2$d (la plus rapide, fichiers plus lourds), %3$d par défaut.','WordPress scales the bigger images down on upload, and keeps them as their original. Longest side, %3$d by default. <strong>0 means no limit: huge images can exhaust the server.</strong>'=>'WordPress réduit les grandes images au téléversement, et les garde comme original. Plus grand côté, %3$d par défaut. <strong>0 signifie sans limite : des images énormes peuvent épuiser le serveur.</strong>','%s compression'=>'Compression %s','%s conversion'=>'Conversion %s']];